const FB="data:image/jpeg;base64,";
// ── 캔버스 & 오프스크린 버퍼 ─────────────────────────────────────
//  화면 캔버스(cv)와 숨겨진 <video>. 렌더는 오프스크린 버퍼에 미리 만든 뒤
//  글리치 효과로 합성한다: baseC(색보정 원본) / redC·cyanC(RGB 채널 분리본).
const cv=document.getElementById('cv'),ctx=cv.getContext('2d'),vid=document.getElementById('vid');
let W,H,DPR,baseC,baseX,redC,redX,cyanC,cyanX,baseReady=false,burst=0;
const fbImg=new Image();fbImg.src=FB;
const imgCache={};
function mkC(){const c=document.createElement('canvas');c.width=W;c.height=H;return[c,c.getContext('2d')];} // 오프스크린 캔버스 생성
// 이미지/영상을 화면 비율에 맞게 꽉 채워(cover) 그리기
function drawCover(x,el){const iw=el.videoWidth||el.width||W,ih=el.videoHeight||el.height||H,s=Math.max(W/iw,H/ih),w=iw*s,h=ih*s;x.drawImage(el,(W-w)/2,(H-h)/2,w,h);}
// 필름 느낌 색보정(세피아·시안·명암 레이어를 합성)
function grade(x){x.globalCompositeOperation='multiply';x.fillStyle='rgba(58,44,26,.34)';x.fillRect(0,0,W,H);
  x.globalCompositeOperation='screen';x.fillStyle='rgba(18,44,52,.20)';x.fillRect(0,0,W,H);
  x.globalCompositeOperation='overlay';x.fillStyle='rgba(0,0,0,.22)';x.fillRect(0,0,W,H);x.globalCompositeOperation='source-over';}
// 소스(el)로부터 오프스크린 버퍼 3종(base·red·cyan) 재생성 — 컷이 바뀌거나 영상 프레임이 갱신될 때 호출
function rebuild(el){if(!el||(!el.width&&!el.videoWidth))el=fbImg;
  baseX.clearRect(0,0,W,H);drawCover(baseX,el);grade(baseX);
  redX.clearRect(0,0,W,H);redX.drawImage(baseC,0,0);redX.globalCompositeOperation='multiply';redX.fillStyle='#ff4a1e';redX.fillRect(0,0,W,H);redX.globalCompositeOperation='source-over';
  cyanX.clearRect(0,0,W,H);cyanX.drawImage(baseC,0,0);cyanX.globalCompositeOperation='multiply';cyanX.fillStyle='#26dcff';cyanX.fillRect(0,0,W,H);cyanX.globalCompositeOperation='source-over';
  baseReady=true;}
// 창 크기 변화 대응: 캔버스 해상도(DPR 반영) 갱신 + 버퍼 재할당
function resize(){DPR=Math.min(2,devicePixelRatio||1);W=innerWidth;H=innerHeight;cv.width=W*DPR;cv.height=H*DPR;cv.style.width=W+'px';cv.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);
  [baseC,baseX]=mkC();[redC,redX]=mkC();[cyanC,cyanX]=mkC();if(cur>=0)applySource();}
addEventListener('resize',resize);

// ── 현재 컷 소스 로딩 ───────────────────────────────────────────
//  cur = 현재 보고 있는 컷 인덱스. 사진은 web/<n>.jpg, 영상은 web/<n>.mp4 로드.
//  로드 성공 시 rebuild()로 버퍼 갱신, 실패하면 fallback 이미지로 대체.
let cur=-1,mode='p',vidReady=false,intensity=0,started=false;
function applySource(){const p=PH[cur];if(!p)return;
  if(p.t==='v'){mode='video';vidReady=false;vid.onloadeddata=()=>{vidReady=true;burst=1;vid.play().catch(()=>{});};
    vid.onerror=()=>{mode='p';rebuild(fbImg);burst=1;};vid.src='web/'+p.n+'.mp4';vid.load();}
  else{mode='p';vidReady=false;const c=imgCache[p.n];if(c){rebuild(c);burst=1;}
    else{const im=new Image();im.onload=()=>{imgCache[p.n]=im;if(cur>=0&&PH[cur].n===p.n){rebuild(im);burst=1;}};im.onerror=()=>{if(cur>=0&&PH[cur].n===p.n){rebuild(fbImg);burst=1;}};im.src='web/'+p.n+'.jpg';}}
}
// ── HUD 갱신 ────────────────────────────────────────────────────
//  setPhoto(i): i번 컷으로 이동 — 좌상단 위경도, 하단 거리/심박/고도/타입,
//  주소, 능선 마커까지 한 번에 갱신. hrHex()는 심박값을 색으로 매핑.
const lat=document.getElementById('lat'),lon=document.getElementById('lon'),mkm=document.getElementById('mkm'),mhr=document.getElementById('mhr'),mele=document.getElementById('mele'),mtype=document.getElementById('mtype'),addrEl=document.getElementById('addr'),pn=document.getElementById('pn'),coordEl=document.getElementById('coord'),stimeEl=document.getElementById('stime');
// 우하단 스탬프 시각: 실제 촬영시각 데이터가 없어, 런 구간(06:12–11:34 KST)을
// 거리(km)에 선형 매핑해 타임라인 따라 흐르게 함. GPX로 정확한 시각을 구우면 대체 가능.
const RUN_START=6*3600+12*60,RUN_END=11*3600+34*60; // 초 단위
const p2=n=>String(n).padStart(2,'0');
function timeAt(km){const f=Math.max(0,Math.min(1,km/D.total)),s=Math.round(RUN_START+f*(RUN_END-RUN_START));return p2(s/3600|0)+':'+p2(s/60%60|0)+':'+p2(s%60);}
function setPhoto(i){i=Math.max(0,Math.min(PH.length-1,i));if(i===cur)return;cur=i;const p=PH[i];
  applySource();
  lat.textContent=p.lat.toFixed(5);lon.textContent=p.lon.toFixed(5);showAddr(p.lat,p.lon);
  mkm.textContent=p.km.toFixed(1)+'km';mhr.textContent='♥'+p.hr;mele.textContent='↑'+p.ele+'m';
  mtype.textContent=p.t==='v'?'▶ 영상':'◻ 사진';mhr.style.color=hrHex(p.hr);
  pn.textContent=p.n;if(stimeEl)stimeEl.textContent=timeAt(p.km);moveMarker(p.km);burst=1;}
function hrHex(hr){const t=(hr-120)/60;return t>.6?'#cf4b34':t>.3?'#f0a23c':'#7fa088';}

// ── 역지오코딩 (좌표 → 구·동 주소) ─────────────────────────────
//  카카오맵 Geocoder로 위경도를 행정동 주소로 변환. 캐시 + 300ms 디바운스로
//  드래그 중 과도한 요청 방지. 실패 시 '—' 표시.
const addrCache={};let addrReq=0,geocoder=null;
if(window.kakao&&kakao.maps)kakao.maps.load(()=>{geocoder=new kakao.maps.services.Geocoder();});
function showAddr(la,lo){const key=la.toFixed(4)+','+lo.toFixed(4);
  if(addrCache[key]!==undefined){addrEl.textContent=addrCache[key]||'—';return;}
  const my=++addrReq;
  setTimeout(()=>{if(my!==addrReq)return;if(!geocoder){addrEl.textContent='—';return;}
    geocoder.coord2RegionCode(lo,la,(res,st)=>{if(my!==addrReq)return;
      if(st===kakao.maps.services.Status.OK){const h=res.find(r=>r.region_type==='H')||res[0];
        const s=((h.region_2depth_name||'')+' '+(h.region_3depth_name||'')).trim();
        addrCache[key]=s;addrEl.textContent=s||'—';}
      else{addrCache[key]='';addrEl.textContent='—';}});
  },300);}

