function buildRidge(){
  let path='M'+rprof.map(p=>rX(p[0]).toFixed(1)+','+rY(p[1]).toFixed(1)).join(' L');
  path+=' L'+rX(RT).toFixed(1)+','+rY(rprof[rprof.length-1][1]).toFixed(1);
  let dots=PH.map(p=>'<circle cx="'+rX(p.km).toFixed(1)+'" cy="'+rY(rEleAt(p.km)).toFixed(1)+'" r="'+(p.t==='v'?3.2:2.4)+'" fill="'+hrHex(p.hr)+'" opacity="0.9"/>').join('');
  rdg.innerHTML='<path d="'+path+'" fill="none" stroke="#e6d8b2" stroke-width="2.2" opacity="0.85" vector-effect="non-scaling-stroke"/>'+dots;}
function moveMarker(km){if(!rmarker)return;rmarker.style.left=(km/D.total*W)+'px';}
buildRidge();

// ── 글리치 렌더 루프 ───────────────────────────────────────────
//  매 프레임 화면을 다시 그린다. 심박(intensity)과 컷 전환 순간(burst)에 따라
//  강도(I)가 정해지고, 이를 기반으로 RGB 채널 분리·흔들림·스캔라인·블록 노이즈를
//  합성해 "흔들린 기록" 느낌을 만든다. targetI()는 심박을 0~1 강도로 환산.
const rnd=(a,b)=>a+Math.random()*(b-a);
function targetI(){if(cur<0)return 0;return Math.max(0,Math.min(1,(PH[cur].hr-120)/60));}
function frame(){requestAnimationFrame(frame);if(!started)return;
  if(mode==='video'&&vidReady&&vid.readyState>=2)rebuild(vid);
  if(!baseReady)return;
  intensity+=(targetI()-intensity)*0.07;if(burst>0)burst-=0.033;
  const I=Math.min(1,intensity*0.1+Math.max(0,burst)*0.9),B=Math.max(0,burst);
  ctx.setTransform(DPR,0,0,DPR,0,0);ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);
  const sh=I*9+B*28,vroll=(B>.3?rnd(-H*.3,H*.3):0);
  ctx.save();ctx.translate(rnd(-sh,sh),rnd(-sh,sh*.6)+vroll);
  const dx=2+I*20+B*34;ctx.globalCompositeOperation='lighter';
  ctx.drawImage(redC,-dx,rnd(-1.5,1.5),W,H);ctx.drawImage(cyanC,dx,rnd(-1.5,1.5),W,H);
  ctx.globalCompositeOperation='source-over';ctx.restore();
  const nt=Math.floor(I*8)+(B>0?7:0);
  for(let k=0;k<nt;k++){const sy=rnd(0,H),hh=rnd(3,24+I*44),ddx=(Math.random()-.5)*(I*W*.22+B*W*.5);ctx.drawImage(cv,0,sy*DPR,W*DPR,hh*DPR,ddx,sy,W,hh);}
  if(Math.random()<I*.5+B){const bw=rnd(40,W*.42),bh=rnd(10,64),sx=rnd(0,W-bw),sy=rnd(0,H-bh);ctx.drawImage(cv,sx*DPR,sy*DPR,bw*DPR,bh*DPR,sx+(Math.random()-.5)*(I*180+B*260),sy,bw,bh);}
  if(Math.random()<.3){const y=rnd(0,H);ctx.fillStyle='rgba(255,255,255,'+(.03+I*.08)+')';ctx.fillRect(0,y,W,rnd(1,3));}
  coordEl.style.textShadow=(-dx*.35)+'px 0 rgba(255,74,30,'+(.45+I*.5)+'),'+(dx*.35)+'px 0 rgba(38,220,255,'+(.45+I*.5)+')';
  coordEl.style.transform='translate('+rnd(-I*5,I*5)+'px,'+(vroll*.04)+'px)';
}
requestAnimationFrame(frame);

// ── 입력 처리 (드래그·키보드·자동재생) ────────────────────────
//  캔버스를 좌우로 드래그하거나(=거리 스크럽), ←/→ 키로 컷 이동.
//  idxFromX(): x좌표 → 가장 가까운 컷 인덱스. autoT는 3.2초 자동 넘김 타이머.
function idxFromX(x){const r=Math.max(0,Math.min(1,x/W)),km=r*D.total;let b=0,bd=1e9;PH.forEach((p,i)=>{const d=Math.abs(p.km-km);if(d<bd){bd=d;b=i;}});return b;}
let down=false;
cv.addEventListener('pointerdown',e=>{down=true;setPhoto(idxFromX(e.clientX));moveMarker(e.clientX/W*D.total);hideHint();stopAuto();cv.setPointerCapture(e.pointerId);});
cv.addEventListener('pointermove',e=>{if(down){setPhoto(idxFromX(e.clientX));moveMarker(e.clientX/W*D.total);}});
cv.addEventListener('pointerup',()=>down=false);
addEventListener('keydown',e=>{if(e.key==='ArrowRight'){setPhoto(cur+1);hideHint();stopAuto();}if(e.key==='ArrowLeft'){setPhoto(cur-1);hideHint();stopAuto();}});
const hint=document.getElementById('hint');let hg=false;function hideHint(){if(!hg){hg=true;hint.style.opacity=0;}}
let autoT=null;function stopAuto(){if(autoT){clearInterval(autoT);autoT=null;}}
function startAuto(){autoT=setInterval(()=>setPhoto(cur>=PH.length-1?0:cur+1),3200);}
// 인트로 화면의 시작 버튼: 인트로를 숨기고 렌더 루프 가동, 첫 컷부터 자동재생 시작.
document.getElementById('go').addEventListener('click',()=>{document.getElementById('intro').classList.add('gone');started=true;resize();setPhoto(0);startAuto();});
resize(); // 초기 레이아웃 계산
